#!/bin/sh
# Bundles the desktop's dogma engine for the iOS app (JavaScriptCore). Needs canopus-desktop checked out
# next to this repo (../canopus-desktop) with its node_modules installed.
set -e
HERE=$(cd "$(dirname "$0")" && pwd)
DESKTOP=$(cd "$HERE/../../../canopus-desktop" && pwd)
"$DESKTOP/node_modules/.bin/esbuild" "$HERE/entry.ts" --bundle --format=iife --target=es2020 --platform=neutral \
  --outfile="$HERE/../../Packages/EVEStaticData/Sources/EVEStaticData/Resources/canopus-dogma.js" \
  --banner:js="// Generated by Tools/dogma-js/build.sh from canopus-desktop $(cd "$DESKTOP" && /usr/bin/git rev-parse --short HEAD). Do not edit."
